float sphere(vec3 ro, vec3 rd, vec3 center, float radius, out vec3 pos) // calcul  de l'intersection entre le rayon et la sphere
{
    vec3 oc = ro - center; // vecteur origine
    float b = dot(oc, rd); // coef 1
    float c = dot(oc, oc) - radius * radius; // coef b
    float h = b * b - c; // discriminant

    if (h < 0.0) return -1.0; // pas d'intersection car -
    h = sqrt(h);

    float t = -b - h; // calcul solution 1
    if (t > 0.0)
    {
        pos = ro + t * rd; // si valide, calcul du point de l'intersection
        return t;
    }

    t = -b + h; // calcul solution 2
    if (t > 0.0)
    {
        pos = ro + t * rd; // ""
        return t;
    }

    return -1.0;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 uv = fragCoord.xy / iResolution.xy * 2.0 - 1.0; // Normalisation
    uv.x *= iResolution.x / iResolution.y;

    vec3 ro = vec3(0.0, 0.0, 3.0); // Position de la caméra (sur l'origine du rayon)
    vec3 rd = normalize(vec3(uv, -1.0)); // Direction du rayon

    vec3 sphereCenter = vec3(0.0, 0.0, 0.0); // Centre de la sphère
    float sphereRadius = 2.0; // Rayon
    vec3 pos; // Position d'intersection

    float t = sphere(ro, rd, sphereCenter, sphereRadius, pos); // calcul de l'intersection

    if (t < 0.0) // si pas d'intersection, fond de couleur
    {
        fragColor = vec4(0.2, 0.6, 1.0, 1.0);
        return;
    }

    // Normale de la sphère au point d'intersection
    vec3 normal = normalize(pos - sphereCenter); // normal de la sphere (pour l'eclairage)

    vec3 lightPos = vec3(2.0 * sin(iTime), 2.0, 2.0 * cos(iTime)); // lumière (qui bouge)
    vec3 lightDir = normalize(lightPos - pos); // direction de la lumiere
    vec3 viewDir = normalize(-pos); // direction de la vue
    vec3 halfDir = normalize(lightDir + viewDir); // direction intermediraire de Blinn-phong

    float diff = max(dot(normal, lightDir), 0.0); // Diffuse (eclairage)
    float spec = pow(max(dot(normal, halfDir), 0.0), 32.0); // Spéculaire (reflet)

    vec3 ambient = vec3(0.1); // Lumière ambiante
    vec3 diffuse = diff * vec3(1.0, 0.9, 0.8); // Lumière diffuse
    vec3 specular = spec * vec3(1.0); // Lumière spéculaire

    vec3 color = ambient + diffuse + specular; // tout combiner donne la couleur de la lumiere

    fragColor = vec4(color, 1.0); // Affichage
}
